1	package com.loja.checkout.service;
2	
3	import com.loja.checkout.clube.NivelClube;
4	import com.loja.checkout.cupom.Cupom;
5	import com.loja.checkout.dto.ItemRequest;
6	import com.loja.checkout.dto.PedidoRequest;
7	import com.loja.checkout.dto.ResumoResponse;
8	import com.loja.checkout.entrega.ModalidadeEntrega;
9	import com.loja.checkout.exception.CheckoutException;
10	import com.loja.checkout.pagamento.FormaPagamento;
11	import com.loja.checkout.pagamento.ResultadoPagamento;
12	import com.loja.checkout.regiao.Regiao;
13	
14	import java.math.BigDecimal;
15	import java.math.RoundingMode;
16	import java.util.List;
17	import java.util.Map;
18	import java.util.function.Function;
19	import java.util.stream.Collectors;
20	
21	import org.springframework.stereotype.Service;
22	
23	@Service
24	public class CheckoutService {
25	
26	    private static final RoundingMode ARREDONDAMENTO = RoundingMode.HALF_EVEN;
27	
28	    private final Map<String, ModalidadeEntrega> modalidades;
29	    private final Map<String, Cupom> cupons;
30	    private final Map<String, FormaPagamento> formasPagamento;
31	    private final Map<String, NivelClube> niveisClube;
32	
33	    public CheckoutService(List<ModalidadeEntrega> modalidadesList,
34	                           List<Cupom> cuponsList,
35	                           List<FormaPagamento> formasPagamentoList,
36	                           List<NivelClube> niveisClubeLista) {
37	        this.modalidades = modalidadesList.stream()
38	                .collect(Collectors.toMap(ModalidadeEntrega::codigo, Function.identity()));
39	        this.cupons = cuponsList.stream()
40	                .collect(Collectors.toMap(Cupom::codigo, Function.identity()));
41	        this.formasPagamento = formasPagamentoList.stream()
42	                .collect(Collectors.toMap(FormaPagamento::codigo, Function.identity()));
43	        this.niveisClube = niveisClubeLista.stream()
44	                .collect(Collectors.toMap(NivelClube::codigo, Function.identity()));
45	    }
46	
47	    public ResumoResponse calcularResumo(PedidoRequest pedido) {
48	        validarItens(pedido.itens());
49	
50	        BigDecimal subtotal = calcularSubtotal(pedido.itens());
51	        BigDecimal pesoTotal = calcularPeso(pedido.itens());
52	
53	        NivelClube nivel = buscar(pedido.nivelClube(), niveisClube, "NIVEL_CLUBE_INVALIDO");
54	
55	        Regiao regiao = buscarRegiao(pedido.regiao());
56	
57	        ModalidadeEntrega modalidade = buscar(pedido.modalidadeEntrega(), modalidades, "MODALIDADE_INVALIDA");
58	        if (!modalidade.disponivel(pesoTotal)) {
59	            throw new CheckoutException("MODALIDADE_INDISPONIVEL");
60	        }
61	
62	        BigDecimal frete = modalidade.calcularFrete(pesoTotal);
63	        if (nivel.freteGratis()) {
64	            frete = BigDecimal.ZERO.setScale(2);
65	        }
66	
67	        BigDecimal descontoCupom = BigDecimal.ZERO.setScale(2);
68	        if (pedido.cupom() != null && !pedido.cupom().isBlank()) {
69	            Cupom cupom = buscar(pedido.cupom(), cupons, "CUPOM_INVALIDO");
70	            if (!cupom.aplicavel(pedido.itens(), subtotal)) {
71	                throw new CheckoutException("CUPOM_NAO_APLICAVEL");
72	            }
73	            descontoCupom = cupom.calcularDesconto(pedido.itens(), subtotal, frete);
74	        }
75	
76	        FormaPagamento formaPagamento = buscar(pedido.formaPagamento(), formasPagamento, "FORMA_PAGAMENTO_INVALIDA");
77	        int parcelas = pedido.parcelas() != null ? pedido.parcelas() : 1;
78	        if (!formaPagamento.parcelamentoValido(parcelas)) {
79	            throw new CheckoutException("PARCELAMENTO_INVALIDO");
80	        }
81	
82	        BigDecimal seguro = subtotal.multiply(regiao.getTaxaSeguro())
83	                .setScale(2, ARREDONDAMENTO);
84	
85	        BigDecimal totalPedido = subtotal
86	                .subtract(descontoCupom)
87	                .add(frete)
88	                .add(seguro)
89	                .setScale(2, ARREDONDAMENTO);
90	
91	        if (!formaPagamento.disponivel(totalPedido)) {
92	            throw new CheckoutException("FORMA_PAGAMENTO_INDISPONIVEL");
93	        }
94	
95	        ResultadoPagamento resultado = formaPagamento.calcular(totalPedido, parcelas);
96	        BigDecimal ajustePagamento = resultado.totalFinal()
97	                .subtract(totalPedido)
98	                .setScale(2, ARREDONDAMENTO);
99	
100	        BigDecimal credito = nivel.calcularCredito(subtotal);
101	        boolean brinde = nivel.brinde(subtotal);
102	
103	        return new ResumoResponse(
104	                subtotal,
105	                descontoCupom,
106	                frete,
107	                modalidade.prazoDias(),
108	                seguro,
109	                ajustePagamento,
110	                resultado.totalFinal(),
111	                parcelas,
112	                resultado.valorParcela(),
113	                credito,
114	                brinde);
115	    }
116	
117	    private void validarItens(List<ItemRequest> itens) {
118	        if (itens == null || itens.isEmpty()) {
119	            throw new CheckoutException("PEDIDO_INVALIDO");
120	        }
121	        for (ItemRequest item : itens) {
122	            if (item.precoUnitario() == null
123	                    || item.precoUnitario().compareTo(BigDecimal.ZERO) <= 0
124	                    || item.quantidade() == null
125	                    || item.quantidade() <= 0
126	                    || item.pesoKg() == null
127	                    || item.pesoKg().compareTo(BigDecimal.ZERO) <= 0) {
128	                throw new CheckoutException("PEDIDO_INVALIDO");
129	            }
130	        }
131	    }
132	
133	    private BigDecimal calcularSubtotal(List<ItemRequest> itens) {
134	        BigDecimal subtotal = BigDecimal.ZERO;
135	        for (ItemRequest item : itens) {
136	            subtotal = subtotal.add(
137	                    item.precoUnitario().multiply(new BigDecimal(item.quantidade())));
138	        }
139	        return subtotal.setScale(2, ARREDONDAMENTO);
140	    }
141	
142	    private BigDecimal calcularPeso(List<ItemRequest> itens) {
143	        BigDecimal peso = BigDecimal.ZERO;
144	        for (ItemRequest item : itens) {
145	            peso = peso.add(item.pesoKg().multiply(new BigDecimal(item.quantidade())));
146	        }
147	        return peso;
148	    }
149	
150	    private <T> T buscar(String codigo, Map<String, T> mapa, String codigoErro) {
151	        if (codigo == null || codigo.isBlank()) {
152	            throw new CheckoutException(codigoErro);
153	        }
154	        T valor = mapa.get(codigo);
155	        if (valor == null) {
156	            throw new CheckoutException(codigoErro);
157	        }
158	        return valor;
159	    }
160	
161	    private Regiao buscarRegiao(String codigo) {
162	        if (codigo == null || codigo.isBlank()) {
163	            throw new CheckoutException("REGIAO_INVALIDA");
164	        }
165	        try {
166	            return Regiao.valueOf(codigo);
167	        } catch (IllegalArgumentException e) {
168	            throw new CheckoutException("REGIAO_INVALIDA");
169	        }
170	    }
171	}
