1	package com.loja.checkout.pagamento;
2	
3	import java.math.BigDecimal;
4	import java.math.RoundingMode;
5	import org.springframework.stereotype.Component;
6	
7	@Component
8	public class Cartao implements FormaPagamento {
9	
10	    private static final BigDecimal TAXA_MENSAL = new BigDecimal("0.0199");
11	
12	    @Override
13	    public String codigo() {
14	        return "CARTAO";
15	    }
16	
17	    @Override
18	    public boolean parcelamentoValido(int parcelas) {
19	        return parcelas >= 1 && parcelas <= 12;
20	    }
21	
22	    @Override
23	    public boolean disponivel(BigDecimal totalPedido) {
24	        return true;
25	    }
26	
27	    @Override
28	    public ResultadoPagamento calcular(BigDecimal totalPedido, int parcelas) {
29	        if (parcelas <= 3) {
30	            BigDecimal valorParcela = totalPedido
31	                    .divide(new BigDecimal(parcelas), 2, RoundingMode.HALF_EVEN);
32	            return new ResultadoPagamento(totalPedido, valorParcela);
33	        }
34	        BigDecimal base = BigDecimal.ONE.add(TAXA_MENSAL);
35	        BigDecimal potencia = base.pow(parcelas);
36	        BigDecimal inversoPotencia = BigDecimal.ONE
37	                .divide(potencia, 20, RoundingMode.HALF_EVEN);
38	        BigDecimal denominador = BigDecimal.ONE.subtract(inversoPotencia);
39	        BigDecimal valorParcela = totalPedido.multiply(TAXA_MENSAL)
40	                .divide(denominador, 2, RoundingMode.HALF_EVEN);
41	        BigDecimal totalFinal = valorParcela.multiply(new BigDecimal(parcelas));
42	        return new ResultadoPagamento(totalFinal, valorParcela);
43	    }
44	}
